1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	} as const satisfies Record<string, number>;
11	
12	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
13	
14	const BLOCK_SIZE = 3;
15	
16	const BLOCK_BASE_PREMIUM = 60;
17	
18	const CURSE_SURCHARGE_RATE = 0.5;
19	
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	
22	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
23	
24	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
25	
26	export type ScenarioResult = { premium: number };
27	
28	export type ScenarioOutcome = { results: ScenarioResult[] };
29	
30	type Item = {
31	  type: InsurableItemType;
32	  cursed?: boolean;
33	  enchantment?: number;
34	};
35	
36	type Scenario = { steps: { items: Item[] }[] };
37	
38	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
39	// customer) round up.
40	const roundPremiumInMHPCOsFavour = (amount: number): number =>
41	  Math.ceil(amount);
42	
43	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
44	  const counts = new Map<InsurableItemType, number>();
45	
46	  for (const item of items) {
47	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
48	  }
49	
50	  return counts;
51	};
52	
53	// Exactly 3 alike components form a building block at a special base premium.
54	const basePremiumForAlikeItems = (
55	  type: InsurableItemType,
56	  count: number,
57	): number =>
58	  count === BLOCK_SIZE
59	    ? BLOCK_BASE_PREMIUM
60	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
61	
62	const basePremiumOf = (items: Item[]): number =>
63	  [...countByItemType(items)]
64	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
65	    .reduce((total, premium) => total + premium, 0);
66	
67	const ownBasePremiumOf = (item: Item): number =>
68	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
69	
70	// Item-specific modifiers apply to the affected item's own base premium,
71	// not to the policy total.
72	type ItemModifier = { appliesTo: (item: Item) => boolean; rate: number };
73	
74	const CURSE_MODIFIER: ItemModifier = {
75	  appliesTo: (item) => item.cursed === true,
76	  rate: CURSE_SURCHARGE_RATE,
77	};
78	
79	const HIGH_ENCHANTMENT_MODIFIER: ItemModifier = {
80	  appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
81	  rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
82	};
83	
84	const itemSurchargeOf = (items: Item[], modifier: ItemModifier): number =>
85	  items
86	    .filter(modifier.appliesTo)
87	    .reduce((total, item) => total + ownBasePremiumOf(item) * modifier.rate, 0);
88	
89	// Policy-wide modifiers are computed from the policy base premium, so the
90	// first insurance surcharge is 10 % of the base — not of base plus curse.
91	const quotePremium = (items: Item[]): number => {
92	  const basePremium = basePremiumOf(items);
93	
94	  return roundPremiumInMHPCOsFavour(
95	    basePremium +
96	      itemSurchargeOf(items, CURSE_MODIFIER) +
97	      itemSurchargeOf(items, HIGH_ENCHANTMENT_MODIFIER) +
98	      basePremium * FIRST_INSURANCE_SURCHARGE_RATE +
99	      PROCESSING_FEE,
100	  );
101	};
102	
103	export const runScenario = (scenario: unknown): ScenarioOutcome => {
104	  const { steps } = scenario as Scenario;
105	
106	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
107	
108	  return { results };
109	};
